 models.dissociation=(l,v)=>{const total=pick([100,200,400,500]),p=pick([10,20,25,40,50,80]),d=total*p/100;return number(v%2?`Из ${total} условных частиц электролита диссоциировало ${d}. Найдите степень диссоциации в процентах.`:`Степень диссоциации электролита ${p}%. Из ${total} условных частиц сколько диссоциировало?`,v%2?p:d,v%2?'%':'','Степень диссоциации — доля исходных частиц, распавшихся на ионы.','α = Nдисс/Nисх · 100%',[v%2?`${d}/${total} · 100%.`:`${total} · ${p}/100.`],{kind:v%2?'fraction':'multiply',...(v%2?{part:d,total}:{a:total,b:p/100})})};
