 models.limiting=(l,v)=>{const h=pick([2,4,6,8]),o=pick([1,2,3,4]),water=Math.min(h,2*o);return number(`Для реакции 2H₂ + O₂ → 2H₂O взяли ${h} моль H₂ и ${o} моль O₂. Найдите максимальное количество воды при полной реакции.`,water,'моль','Выход ограничен реагентом с меньшим отношением n/ν.','n(H₂O) = min(n(H₂)/2, n(O₂)) · 2',[`По H₂ можно получить ${h} моль воды; по O₂ — ${2*o} моль.`,`Выбираем меньшее значение: ${water}.`],{kind:'limiting',h,o})};
